@pytest.mark.asyncio
async def test_start_and_close():
    """Test starting and closing the manager with SingleWorkerPool."""
    manager = ExecutionManager({
        "pool": (SingleWorkerPool, {}),
    })

    await manager.start()
    assert manager._started is True
    assert "pool" in manager._pools
